import{z as i,x as s,o as E,c as m,q as B,j as l,D as e,d as t,s as o,S as A,b as r}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"对冲的执行细节","description":"","frontmatter":{"title":"对冲的执行细节","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/omm-hedge-execution.md","filePath":"quant/omm-hedge-execution.md","lastUpdated":1791063341000}'),d={name:"quant/omm-hedge-execution.md"};function p(h,a,u,D,c,f){const n=s("Mermaid");return E(),m("div",null,[a[2]||(a[2]=B('<h1 id="对冲的执行细节" tabindex="-1">对冲的执行细节 <a class="header-anchor" href="#对冲的执行细节" aria-label="Permalink to &quot;对冲的执行细节&quot;">​</a></h1><div class="epigraph"><p>对冲公式给出的是张数，不是订单；从张数到成交之间损失的每一跳，都直接从波动率边际里扣。</p><footer>—— 据 Hull, Options, Futures, and Other Derivatives 希腊字母与动态对冲各章；执行细节据做市实务整理</footer></div><p><a href="/quant/omm-curve-maintenance">上一课</a>把 quoted 曲线维护成受控管线；报价被吃、账上生成 <a href="/quant/omm-book-layering">手层</a> 批次，同时生成一笔标的缺口。<a href="/quant/delta-hedge-freq">Delta 对冲频率</a> 回答了「何时补」，本课回答「怎么补」：用什么工具、什么订单、什么节奏把缺口填上，滑点记到哪本账。频率课讲带宽，本课讲带宽内的手艺。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公式说补 \\(\\Delta\\) 张。执行要回答四个公式没有的问题：用现货、期货还是期权补；用市价单、可成交限价还是挂单；立刻补、按时点补还是触发补；补完的滑点算进哪一笔盈亏。答错任何一条，波动率边际都会被侵蚀——卖出隐波 1 个点的优势，可以在大 Gamma 日的追价里全额回吐，账面显示「波动看对了却没赚到」。</p><p>对冲还反向作用于行情：短 Gamma 台的再平衡是买涨卖跌，趋势日里与自身对冲需求同向竞争的单子不止你一家。执行方案必须把「自己也是冲击来源」算进去。</p><p><span class="marginnote">术语翻译：参与率上限，就是「自己的单子最多占这段时间市场成交量的百分比」。设 10% 的意思是：市场每成交 10 手，你最多吃 1 手——不是不许下大单，是不许比整个市场本身更急。</span></p><h3 id="工具、订单与节奏" tabindex="-1">工具、订单与节奏 <a class="header-anchor" href="#工具、订单与节奏" aria-label="Permalink to &quot;工具、订单与节奏&quot;">​</a></h3><p><strong>工具</strong>：现货杠杆与借用成本高、但无基差；期货有保证金效率、有换月与基差；期权补 Delta 会带进新的 Gamma 与 Vega，属于 <a href="/quant/vanna-volga">Vanna / Volga</a> 那类二阶管理。选择由缺口大小、持有期与可用保证金共同决定。<strong>订单</strong>：缺口必须立即消除（隔夜前的裸 Gamma、事件前的超标）用可成交限价封顶滑点；带内回补用挂单 <a href="/quant/optimal-limit-placement">按队列位置</a> 等 <a href="/quant/cks-optimal-placement">成交概率</a>，等不到再升级。<strong>节奏</strong>：到点补（每半小时或收盘）可预测、可摊薄；触带补（Delta 出带才动）省单但慢半拍；两者混合最常见——到点小额、触带大额。</p><p><span class="marginnote">滑点必须按到达价（下单决策那一刻的中间价）记账：一张缺口 500 张的期货单，成交均价比决策时中点差 0.05%，对 5000 点的指数就是 12.5 点，接近隐波十分之一个点。不按到达价记，执行损耗会伪装成「波动没看对」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把执行写成与 <a href="/quant/omm-greeks-limits">限额</a> 同级的规则表：每类缺口（日内补、收盘补、事件前补）对应工具、订单类型、参与率上限与升级路径。参与率设上限（例如不超过盘口几分钟成交量的固定比例），大单拆 <a href="/quant/almgren-chriss">时间表</a> 或按 <a href="/quant/bouchaud-propagator">冲击的传播</a> 分批。收盘补有专门规则：收盘前的缺口按「愿付滑点上限」执行，因为 <a href="/quant/overnight-gap-hedge">隔夜跳空</a> 的损失期望远大于日内滑点。每笔对冲单事后记三笔账：到达价滑点、费用、以及「不补会怎样」的对照——对照项是校准执行规则的唯一依据。</p><p><span class="marginnote">术语翻译：到达价滑点，指的是拿「下单决策那一刻的盘口中间价」当原点，去量成交均价偏了多少。它与「比收盘价高还是低」的区别在于：后者把运气也算成绩，前者才能把执行手艺单独拎出来改进。</span></p>',13)),(E(),l(A,null,{default:e(()=>[o(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22Delta%20%E7%BC%BA%E5%8F%A3%22%5D%20--%3E%20B%7B%22%E7%BC%BA%E5%8F%A3%E7%B1%BB%E5%9E%8B%22%7D%0A%20%20B%20--%3E%7C%E8%A3%B8%20Gamma%20%E6%88%96%E8%B6%85%E6%A0%87%7C%20C%5B%22%E5%8F%AF%E6%88%90%E4%BA%A4%E9%99%90%E4%BB%B7%20%E7%AB%8B%E5%8D%B3%22%5D%0A%20%20B%20--%3E%7C%E5%B8%A6%E5%86%85%E5%9B%9E%E8%A1%A5%7C%20D%5B%22%E6%8C%82%E5%8D%95%E6%8E%92%E9%98%9F%20%E8%B6%85%E6%97%B6%E5%8D%87%E7%BA%A7%22%5D%0A%20%20B%20--%3E%7C%E5%A4%A7%E9%A2%9D%E5%AE%9A%E6%97%B6%7C%20E%5B%22%E6%8B%86%E5%8D%95%20%E6%8C%89%E5%8F%82%E4%B8%8E%E7%8E%87%22%5D%0A%20%20C%20--%3E%20F%5B%22%E6%88%90%E4%BA%A4%E5%9B%9E%E6%8A%A5%22%5D%0A%20%20D%20--%3E%20F%0A%20%20E%20--%3E%20F%0A%20%20F%20--%3E%20G%5B%22%E6%8C%89%E5%88%B0%E8%BE%BE%E4%BB%B7%E8%AE%B0%E6%BB%91%E7%82%B9%22%5D%0A%20%20G%20--%3E%20H%5B%22%E5%AF%B9%E7%85%A7%20%E4%B8%8D%E8%A1%A5%E4%BC%9A%E6%80%8E%E6%A0%B7%22%5D%0A%20%20H%20--%3E%20A%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"到达价为什么是记账核心：执行质量的度量若挂在「成交均价对比收盘价」上，运气可以顶替手艺；到达价把「决策时刻的中间价」固定为原点，滑点成为可归因、可改进的量。升级路径为什么必须有时限：挂单省的是价差、赌的是排队，短 Gamma 台在趋势里等排队，等于让 \\(\\tfrac12\\Gamma(\\Delta S)^2\\) 每分钟生长——时限是价差节约与 Gamma 损耗的换算，写进规则而不是留给盘感。",-1)),(E(),l(A,null,{default:e(()=>[o(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%8C%82%E5%8D%95%E6%8E%92%E9%98%9F%20%E7%9C%81%E5%8D%8A%E4%BB%B7%E5%B7%AE%22%5D%20--%3E%20B%7B%22%E8%B6%85%E6%97%B6%E4%B8%8A%E9%99%90%E5%88%B0%E4%BA%86%3F%22%7D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20A%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20D%5B%22%E7%AE%97%E4%B8%A4%E7%AC%94%E8%B4%A6%20%E4%BB%B7%E5%B7%AE%E8%8A%82%E7%BA%A6%20%E5%AF%B9%20Gamma%20%E6%8D%9F%E8%80%97%22%5D%0A%20%20D%20--%3E%20E%7B%22%E8%8A%82%E7%BA%A6%E4%BB%8D%E5%8D%A0%E4%BC%98%3F%22%7D%0A%20%20E%20--%3E%7C%22%E6%98%AF%22%7C%20C%5B%22%E7%BB%A7%E7%BB%AD%E6%8E%92%E9%98%9F%22%5D%0A%20%20E%20--%3E%7C%22%E5%90%A6%22%7C%20F%5B%22%E5%8D%87%E7%BA%A7%E5%8F%AF%E6%88%90%E4%BA%A4%E9%99%90%E4%BB%B7%20%E5%B0%81%E9%A1%B6%E6%BB%91%E7%82%B9%22%5D%0A%20%20F%20--%3E%20G%5B%22%E7%BC%BA%E5%8F%A3%E6%B6%88%E9%99%A4%20%E5%9B%9E%E5%86%99%E6%BB%91%E7%82%B9%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20C%20--%3E%20A%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p>期货与现货的换算也要进机制层：Beta 调整、股息与借券成本折算、换月日的双腿，任何一处口径不一致，Delta 就不是账本以为的那个 Delta。到期周还要把 <a href="/quant/discrete-hedge-error">离散对冲误差</a> 的量级记在心上：误差是平方根级的，滑点预算应与之同阶。</p><p>不这么做会错在哪：没有滑点台账的台，执行规则永远在「感觉上还行」的状态；有台账但不做对照的台，会把好年景的运气当成好规则，直到一次大跳空把差异摊开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>对冲执行不解决概念错误：用期权补 Delta 带进二阶暴露，那是 <a href="/quant/vanna-volga">Vanna / Volga</a> 的课；流动性枯竭日参与率上限形同虚设，规则表要有「不可执行」分支——宁可持仓过夜也不追一口价，是限额问题不是执行问题。停牌与熔断类机制下，最好的订单也发不出去，事件前削减才是唯一的对冲。最后，执行数据本身要进 <a href="/quant/omm-book-layering">账本</a>：时间戳到毫秒，否则到达价无从谈起。</p><p><span class="marginnote">常见误区：初学者容易以为执行的目标是「滑点越低越妙」。实际上滑点是预算不是敌人：隔夜跳空的损失期望远大于日内滑点，收盘前该花滑点就花；把滑点省在错误的时刻，才是真正贵的执行。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>频率课定带宽，本课定带宽内的手艺：工具、订单、节奏、记账四件事。</li><li>立即消除的缺口用可成交限价封顶滑点；带内回补挂单排队，超时升级。</li><li>滑点按到达价记账并做「不补会怎样」的对照，执行规则才有校准依据。</li><li>参与率上限与拆单是对自己冲击的控制；收盘补按愿付滑点上限执行。</li><li>工具换算（Beta、借券、换月）错一处，Delta 就不是账本的 Delta。</li><li>出处：据 Hull, <em>Options, Futures, and Other Derivatives</em>；到达价与执行规则据做市实务整理。</li></ul>',7))])}const q=i(d,[["render",p]]);export{C as __pageData,q as default};
